# Общие JS-хелперы. fx: число рядом с порогом показывается с таким числом
# значащих цифр, чтобы округлённое значение лежало по ту же сторону порога,
# что и точное (правило партий №2–3). OPT: необязательное поле — пустое
# даёт null, нечисловое — NaN (строгий ввод сохраняется).
O_JS = r'''
function gt(a,b){return a>b*(1+1e-12);}
function ge(a,b){return a>=b*(1-1e-12);}
function le(a,b){return a<=b*(1+1e-12);}
function fx(x,lim){if(Math.abs(x-lim)<=Math.abs(lim)*1e-12)return fmt(x,4);for(var p=4;p<=12;p++){var r=Number(x.toPrecision(p));if(x<lim?r<lim:r>lim)return fmt(x,p);}return fmt(x,12);}
function OPT(id){var el=$(id);if(!el)return null;if(String(el.value).trim()==='')return null;return P(id);}
'''

