js=O_JS + r'''
function calc(){
var u1=P('u1'),u2=P('u2'),r1=P('r1'),r2=P('r2'),rw=P('rw'),ich=P('ich'),idis=P('idis'),fu=OPT('inf'),same=S('same')==='same';
if([u1,u2,r1,r2,rw,ich,idis].some(isNaN))return err('Заполните напряжения, сопротивления и допустимые токи.');
if(u1<=0||u2<=0||u1>1000||u2>1000)return err('Напряжения АКБ — больше 0 и не больше 1000 В.');
if(r1<=0||r2<=0)return err('Внутреннее сопротивление АКБ должно быть больше нуля.');
if(rw<0)return err('Сопротивление перемычек не может быть отрицательным.');
if(ich<=0||idis<=0)return err('Допустимые токи заряда и разряда должны быть больше нуля.');
if(fu!==null){if(isNaN(fu))return err('Номинал предохранителя — число в амперах. Если предохранителя нет, оставьте поле пустым.');if(fu<=0)return err('Номинал предохранителя должен быть больше нуля.');}
var du=Math.abs(u1-u2),rs=(r1+r2+rw)/1000,i0=du/rs,lim=Math.min(ich,idis),lo=u1<u2?'первая':'вторая',hi=u1<u2?'вторая':'первая',big=du>0.25*Math.max(u1,u2)*(1+1e-12);
if(!isFinite(i0))return err('Значения вне диапазона надёжного расчёта.');
var h=row('Разница напряжений покоя ΔU',fmt(du,4)+' В'+(du>0?' — сильнее разряжена '+lo+' АКБ':''))+
 row('Сопротивление контура R1 + R2 + Rпер',fmt(rs*1000,4)+' мОм')+
 row('Начальный ток выравнивания I = ΔU / ΣR',fx(i0,lim)+' А');
if(du>0)h+=row('Допустимый ток заряда ('+lo+' АКБ) / разряда ('+hi+' АКБ)',fx(ich,i0)+' / '+fx(idis,i0)+' А');
h+=row('Разница напряжений, при которой ток равен допустимому',fx(lim*rs,du)+' В')+
 row('Мощность потерь в контуре в первый момент ΔU·I',fmt(du*i0,4)+' Вт');
if(fu!==null)h+=row('Ток относительно номинала предохранителя',fx(i0/fu,1)+'·In');
var st,over=gt(i0,ich)||gt(i0,idis);
if(big)st='Не соединяйте параллельно: напряжения различаются больше чем на четверть — так отличаются батареи разного номинального напряжения или глубоко разряженная батарея. Параллельно соединяют батареи одного номинального напряжения, а глубоко разряженную сначала заряжают отдельно';
else if(over)st='Начальный ток выравнивания '+fx(i0,lim)+' А больше допустимого '+(gt(i0,ich)&&gt(i0,idis)?'тока заряда и разряда':(gt(i0,ich)?'тока заряда':'тока разряда'))+' — до соединения уменьшите разницу напряжений до '+fx(lim*rs,du)+' В, выровняв заряд АКБ'+(same?'':'; батареи к тому же разные — допустима ли их параллельная работа, указано в паспорте');
else if(!same)st='Недостаточно данных: батареи разные — допустима ли их параллельная работа, указано в паспорте; начальный ток показан справочно';
else if(du===0)st='Оценка: напряжения покоя равны — в первый момент ток выравнивания не возникает';
else if(fu!==null&&gt(i0,fu))st='Риск срабатывания предохранителя: начальный ток '+fx(i0,fu)+' А больше его номинала '+fx(fu,i0)+' А, хотя и в пределах допустимых токов АКБ';
else st='Оценка: начальный ток выравнивания '+fx(i0,lim)+' А не больше допустимых токов АКБ';
var n='Ток в первый момент после соединения наибольший: дальше напряжения сближаются, и он спадает. Батарея с меньшим напряжением заряжается, с большим — разряжается тем же током, поэтому ток сравнивается с обоими пределами. ';
n+='Внутреннее сопротивление в паспорте часто дано как максимум («не более»): при меньшем фактическом сопротивлении ток больше расчётного. ';
if(over&&!big)n+='Вывод следует из самого расчёта: ток пропорционален разнице напряжений, поэтому до соединения её уменьшают — например, заряжают каждую батарею отдельно до одинакового напряжения покоя. ';
if(fu!==null&&gt(i0,fu))n+='Сработает ли предохранитель, зависит от длительности тока — по его время-токовой характеристике. ';
n+='На плюсовом выводе каждой батареи ставят свой предохранитель (Victron); ток выравнивания течёт через оба. ';
if(!same)n+='Разные батареи делят ток неравно и после выравнивания. Victron для батарей Lithium NG допускает в параллели разную ёмкость и возраст (желательны одинаковые), а одинаковые ёмкость и артикул требует внутри последовательной цепочки; для других батарей — по их паспорту. ';
n+='У LiFePO₄ напряжение покоя мало меняется на большей части диапазона заряда: малая разница напряжений может означать большую разницу заряда, и ток спадает медленно.';
out(h+row('Статус',st)+note(n));
}
''',
about="""<div class="formula">I<sub>0</sub> = |U<sub>1</sub> − U<sub>2</sub>| / (R<sub>1</sub> + R<sub>2</sub> + R<sub>пер</sub>)<br>ΔU<sub>доп</sub> = min(I<sub>заряда</sub>, I<sub>разряда</sub>) · (R<sub>1</sub> + R<sub>2</sub> + R<sub>пер</sub>)</div>
<p><b>Откуда ток.</b> Каждая батарея — источник ЭДС, равной её напряжению покоя, с внутренним сопротивлением. При параллельном соединении они образуют один контур: по правилу Кирхгофа ток в нём равен разности ЭДС, делённой на сумму всех сопротивлений контура, — внутренних сопротивлений обеих батарей, перемычек, предохранителей и контактов. Внутренние сопротивления — миллиомы, поэтому даже полвольта разницы дают десятки ампер. Батарея с большим напряжением разряжается, с меньшим — заряжается тем же током.</p>
<p><b>С чем сравнивать.</b> Ток в первый момент — наибольший: дальше напряжения сближаются, и ток спадает. Его сравнивают с допустимым током заряда более разряженной батареи и с допустимым током разряда более заряженной — по паспорту и по порогам BMS. Калькулятор показывает и разницу напряжений, при которой начальный ток как раз равен меньшему из этих пределов.</p>
<p><b>Точность.</b> Внутреннее сопротивление меняется с зарядом, температурой и временем, а в паспорте его часто дают как максимум («не более»). При меньшем фактическом сопротивлении ток больше расчётного, поэтому вывод «в пределах» — только оценка, а вывод «больше допустимого» при паспортных максимумах тем более верен. У LiFePO₄ напряжение покоя почти не меняется на большей части диапазона заряда (TI): малая разница напряжений может скрывать большую разницу заряда, и ток спадает медленно.</p>
<p><b>Что говорит изготовитель.</b> Victron в руководстве по литиевым батареям Smart требует заряжать каждую батарею отдельно перед сборкой последовательной цепочки; одну батарею или банк из параллельно соединённых батарей можно заряжать как одну. На плюсовом выводе каждой батареи ставят свой предохранитель, а кабели подключают так, чтобы путь тока через каждую батарею был одинаковым. Для батарей Lithium NG Victron допускает в параллели разную ёмкость и возраст — одинаковые лишь желательны, — а одинаковые ёмкость и артикул требует внутри последовательной цепочки. Вывод о выравнивании заряда перед параллельным соединением калькулятор делает из самого расчёта: если начальный ток больше допустимого, разницу напряжений уменьшают до ΔU<sub>доп</sub>.</p>
<p><b>Разное номинальное напряжение.</b> Если напряжения покоя различаются больше чем на четверть, это уже не разница заряда одинаковых батарей, а батареи разного номинального напряжения (например, 25,6 и 12,8 В) или глубоко разряженная батарея. Такие батареи параллельно не соединяют: калькулятор вместо совета выровнять заряд выдаёт «не соединяйте». Порог в четверть — граница калькулятора, а не норма.</p>
<p><b>Чем отличается от расчёта сборки.</b> <a href="batareya-posledovatelno-parallelno.html">Калькулятор сборки батареи S/P</a> считает напряжение, ёмкость и энергию уже собранного банка. Эта страница — о моменте соединения: какой ток пойдёт между батареями, если их напряжения разные. Внутреннее сопротивление по просадке под нагрузкой оценивает <a href="vnutrennee-soprotivlenie.html">калькулятор внутреннего сопротивления</a>, сопротивление перемычки — <a href="soprotivlenie-provoda.html">калькулятор сопротивления провода</a>.</p>""",
example="""<p>Две батареи LiFePO₄ 12,8 В 100 А·ч одной модели. По паспорту ECO-WORTHY 1100700112: внутреннее сопротивление 25 мОм, рекомендуемый ток заряда 50 А (наибольший 100 А), ток разряда 100 А. Напряжения покоя 13,4 и 12,9 В, перемычки с предохранителями — 2 мОм. Начальный ток: 0,5 / (0,025 + 0,025 + 0,002) = 0,5 / 0,052 ≈ <b>9,615 А</b> — меньше 50 А. Ток сравняется с 50 А при разнице 50 · 0,052 = 2,6 В.</p>
<p>Если фактическое сопротивление батарей по 5 мОм, а перемычек 1 мОм, при разнице 1 В ток 1 / 0,011 ≈ <b>90,91 А</b> — больше 50 А: заряд нужно выровнять до соединения.</p>""",
